def only_in_first(a, b):
    i = j = 0
    out = []
    while i < len(a):
        if j < len(b) and b[j] < a[i]:
            j += 1
        elif j < len(b) and b[j] == a[i]:
            i += 1
        else:
            if not out or out[-1] != a[i]:
                out.append(a[i])
            i += 1
    return out

