static int[] onlyInFirst(int[] a, int[] b) {
    int i = 0, j = 0, w = 0;
    int[] out = new int[a.length];
    while (i < a.length) {
        if (j < b.length && b[j] < a[i]) j++;
        else if (j < b.length && b[j] == a[i]) i++;
        else {
            if (w == 0 || out[w - 1] != a[i])
                out[w++] = a[i];
            i++;
        }
    }
    return Arrays.copyOf(out, w);
}

