vector<int> onlyInFirst(const vector<int>& a, const vector<int>& b) {
    size_t i = 0, j = 0;
    vector<int> out;
    while (i < a.size()) {
        if (j < b.size() && b[j] < a[i]) j++;
        else if (j < b.size() && b[j] == a[i]) i++;
        else {
            if (out.empty() || out.back() != a[i])
                out.push_back(a[i]);
            i++;
        }
    }
    return out;
}

