int onlyInFirst(const int* a, int na, const int* b, int nb, int* out) {
    int i = 0, j = 0, w = 0;
    while (i < na) {
        if (j < nb && b[j] < a[i]) j++;
        else if (j < nb && b[j] == a[i]) i++;
        else {
            if (w == 0 || out[w - 1] != a[i])
                out[w++] = a[i];
            i++;
